<?php requireRole('student'); $cid=(int)($_GET['course_id']??0);$s=$pdo->prepare('SELECT c.title_en,c.title_ar,p.percent_complete,u.full_name FROM progress p JOIN courses c ON c.id=p.course_id JOIN users u ON u.id=p.student_id WHERE p.student_id=? AND p.course_id=?');$s->execute([userId(),$cid]);$r=$s->fetch();if(!$r||$r['percent_complete']<100){http_response_code(403);exit('Certificate is available after completing the course.');} ?>
<div class="hero"><h1>🎓 Certificate of Completion</h1><p>This certifies that</p><h2><?=h($r['full_name'])?></h2><p>has completed</p><h2><?=h(lang()==='ar'?$r['title_ar']:$r['title_en'])?></h2><p>CodeBridge • <?=date('Y-m-d')?></p><button class="btn" onclick="window.print()">Print / Save as PDF</button></div>
